import{_ as a,o,c as r,ag as i}from"./chunks/framework.CrXGS008.js";const z=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"pl/faq.md","filePath":"pl/faq.md"}'),t={name:"pl/faq.md"};function n(c,e,d,s,l,y){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="konsola-wyswietla-you-lack-the-required-entitlement" tabindex="-1">Konsola wyświetla <code>You lack the required entitlement</code> <a class="header-anchor" href="#konsola-wyswietla-you-lack-the-required-entitlement" aria-label="Permalink to &quot;Konsola wyświetla `You lack the required entitlement`&quot;">​</a></h2><p>Skrypt nie jest powiązany z kontem Cfx.re, do którego należy klucz licencyjny serwera. Sprawdź w <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a>, czy konto, które kupiło skrypt, jest tym samym, które utworzyło klucz w <code>sv_licenseKey</code>. Uprawnienia (entitlements) są odczytywane przy starcie serwera: po nowym zakupie zrestartuj cały serwer, <code>restart</code> samego zasobu nie wystarczy.</p><h2 id="could-not-find-dependency-nay-lib-for-resource-nay-car-wash" tabindex="-1"><code>Could not find dependency nay_lib for resource nay_car_wash</code> <a class="header-anchor" href="#could-not-find-dependency-nay-lib-for-resource-nay-car-wash" aria-label="Permalink to &quot;`Could not find dependency nay_lib for resource nay_car_wash`&quot;">​</a></h2><p><code>nay_lib</code> musi startować przed każdym skryptem Nayretis, a oba foldery muszą znajdować się w folderze <code>resources</code>. Sprawdź kolejność linii <code>ensure</code> w <code>server.cfg</code>: <code>ensure nay_lib</code> jest pierwszy, po zasobach frameworka, ekwipunku i targetu.</p><h2 id="no-supported-framework-detected" tabindex="-1"><code>No supported framework detected</code> <a class="header-anchor" href="#no-supported-framework-detected" aria-label="Permalink to &quot;`No supported framework detected`&quot;">​</a></h2><p>Uruchamiaj <code>nay_lib</code> po zasobie frameworka. Jeśli wykrywanie dalej zawodzi, wymuś framework w <code>server.cfg</code>, na przykład <code>setr nay:framework &quot;esx&quot;</code>. Dostępne wartości są na stronie <a href="/pl/bridge/">Bridge</a>. Używasz nieobsługiwanego frameworka? Napisz <a href="/pl/bridge/custom">własny adapter</a>.</p><h2 id="błedy-bazy-danych-przy-starcie" tabindex="-1">Błędy bazy danych przy starcie <a class="header-anchor" href="#błedy-bazy-danych-przy-starcie" aria-label="Permalink to &quot;Błędy bazy danych przy starcie&quot;">​</a></h2><p><code>oxmysql</code> musi być uruchomiony przed <code>nay_lib</code> i połączony z bazą danych (<code>mysql_connection_string</code> w <code>server.cfg</code>). Tabele tworzą się przy pierwszym uruchomieniu, więc użytkownik bazy danych musi mieć prawo do tworzenia tabel.</p><h2 id="jak-zmienic-jezyk" tabindex="-1">Jak zmienić język? <a class="header-anchor" href="#jak-zmienic-jezyk" aria-label="Permalink to &quot;Jak zmienić język?&quot;">​</a></h2><p>Otwórz <code>/nay</code>, potem <strong>Nayretis</strong>, potem <strong>Język</strong>. Dostępne są angielski, francuski, hiszpański, portugalski, polski i niemiecki, a wybrany język obowiązuje we wszystkich skryptach Nayretis. <code>setr nay:locale &quot;fr&quot;</code> w <code>server.cfg</code> ustawia język używany, dopóki nikt nie zmieni go w grze.</p><h2 id="ktore-pliki-moge-edytowac" tabindex="-1">Które pliki mogę edytować? <a class="header-anchor" href="#ktore-pliki-moge-edytowac" aria-label="Permalink to &quot;Które pliki mogę edytować?&quot;">​</a></h2><ul><li><code>config.lua</code> każdego skryptu: opcjonalne wartości początkowe. Obowiązują, dopóki ustawienie nie zostanie zmienione w <code>/nay</code>, a <strong>Przywróć</strong> wraca do nich.</li><li><code>locales/*.json</code>: wszystkie teksty wyświetlane graczom.</li><li><code>nay_lib/bridge/custom.lua</code>: Twój własny adapter frameworka.</li></ul><p>Reszta kodu jest chroniona przez Cfx escrow.</p><h2 id="czy-nay-lib-sie-z-czyms-łaczy" tabindex="-1">Czy nay_lib się z czymś łączy? <a class="header-anchor" href="#czy-nay-lib-sie-z-czyms-łaczy" aria-label="Permalink to &quot;Czy nay_lib się z czymś łączy?&quot;">​</a></h2><p>Przy starcie <code>nay_lib</code> odczytuje publiczny plik wersji (<code>https://versions.nayretis.com/versions.json</code>) i informuje w konsoli, gdy dostępna jest aktualizacja. Wyłączysz to przez <code>set nay:versionCheck false</code>. Nic innego nie opuszcza serwera, chyba że włączysz <a href="/pl/nay-lib/api">API HTTP</a> albo dodasz <a href="/pl/nay-lib/webhooks">webhooki</a>.</p><h2 id="gdzie-znajde-pomoc" tabindex="-1">Gdzie znajdę pomoc? <a class="header-anchor" href="#gdzie-znajde-pomoc" aria-label="Permalink to &quot;Gdzie znajdę pomoc?&quot;">​</a></h2><p>Załóż wątek na kanale <code>#support</code> na <a href="https://discord.gg/HqNyFsDBmw" target="_blank" rel="noreferrer">Discordzie Nayretis</a>, jeden wątek na problem, podając skrypt i jego wersję, framework, ekwipunek i target oraz błędy z konsoli serwera i F8.</p>',18)])])}const k=a(t,[["render",n]]);export{z as __pageData,k as default};
